// Package script renders selected config items into a bash script.
package script

import (
	"fmt"
	"slices"
	"strings"

	"github.com/FelixDes/arch_post_install/internal/config"
)

var mgrCommands = map[string]string{
	"yay":    "yay -S --needed --noconfirm --answerdiff=None --answeredit=None",
	"paru":   "paru -S --needed --noconfirm --skipreview",
	"pacman": "sudo pacman -S --needed --noconfirm",
}

const prelude = `#!/usr/bin/env bash
# Generated by arch_post_install
set -euo pipefail

mgr() { %s "$@"; }
notify() { notify-send -i dialog-information -t 5000 -u critical "$@"; }
step() { printf '\n\033[1;34m==> %%s\033[0m\n' "$*"; }
`

// AUR helpers are not in the official repos, so a fresh install needs them built first.
const bootstrap = `
if ! command -v %[1]s >/dev/null; then
  step "Bootstrap %[1]s"
  sudo pacman -S --needed --noconfirm git base-devel
  tmp=$(mktemp -d)
  git clone https://aur.archlinux.org/%[1]s-bin.git "$tmp/%[1]s-bin"
  (cd "$tmp/%[1]s-bin" && makepkg -si --noconfirm)
  rm -rf "$tmp"
fi
`

// Render builds the script: all packages are installed in one transaction,
// then each item's snippet runs in its own subshell, then the after snippet.
func Render(helper string, items []*config.Item, after string) string {
	var b strings.Builder
	fmt.Fprintf(&b, prelude, mgrCommands[helper])
	if helper != "pacman" {
		fmt.Fprintf(&b, bootstrap, helper)
	}

	var pkgs []string
	for _, it := range items {
		for _, p := range it.Packages {
			if !slices.Contains(pkgs, p) {
				pkgs = append(pkgs, p)
			}
		}
	}
	if len(pkgs) > 0 {
		b.WriteString("\nstep \"Install packages\"\nmgr")
		for _, p := range pkgs {
			b.WriteString(" \\\n  " + p)
		}
		b.WriteString("\n")
	}

	for _, it := range items {
		if it.Run != "" {
			writeStep(&b, it.Name, it.Run)
		}
	}
	if after != "" {
		writeStep(&b, "After", after)
	}
	return b.String()
}

func writeStep(b *strings.Builder, name, body string) {
	// The body is not indented: that would change multi-line strings and heredocs.
	fmt.Fprintf(b, "\nstep %s\n(\n%s\n)\n", quote(name), strings.TrimRight(body, "\n"))
}

func quote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}
